"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["71781"],{74509(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.carater_nao_admitido_pelo_tipo","status":422,"titulo":"O tipo de etapa n\xe3o admite o car\xe1ter declarado"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.carater_nao_admitido_pelo_tipo","requisitos":[],"oQueAconteceu":["Cada tipo de etapa do cadastro do m\xf3dulo Configura\xe7\xe3o declara se admite\\npontua\xe7\xe3o (compor a nota final) e se admite elimina\xe7\xe3o (reprovar candidato). O\\ncar\xe1ter declarado para a etapa precisa caber no que o tipo admite:","- car\xe1ter classificat\xf3rio ou ambas, com tipo que n\xe3o admite pontua\xe7\xe3o: a mensagem\\n  diz que o tipo n\xe3o comp\xf5e a nota final;\\n- car\xe1ter eliminat\xf3rio ou ambas, com tipo que n\xe3o admite elimina\xe7\xe3o: a mensagem\\n  diz que o tipo n\xe3o elimina candidato.","A recusa vem em `etapas[n].carater`, e a mensagem traz o nome do tipo. Com car\xe1ter\\n\\"ambas\\", os dois casos s\xe3o conferidos separadamente, e a mesma etapa pode receber\\nduas recusas com este c\xf3digo.","A confer\xeancia \xe9 uma passada pr\xf3pria, depois da confer\xeancia da forma de todas as\\netapas e antes de qualquer altera\xe7\xe3o no processo, e acumula as recusas de todas as\\netapas no array `errors[]`. S\xf3 \xe9 feita para a etapa nova, para a que troca de tipo\\ne para a que muda de car\xe1ter: a etapa que mant\xe9m o tipo e o car\xe1ter n\xe3o \xe9\\nreavaliada. Se o tipo foi desativado depois que a etapa o escolheu e o v\xednculo se\\nmant\xe9m, a confer\xeancia usa o que o tipo admitia quando a etapa o escolheu; com tipo\\nque n\xe3o existe ou n\xe3o est\xe1 ativo e v\xednculo novo, a recusa \xe9 outra\\n([`tipo_etapa_nao_encontrado_ou_inativo`](/erros/uniplus.selecao.processo_seletivo.tipo_etapa_nao_encontrado_ou_inativo))."],"comoResolver":["Mude o car\xe1ter para um que o tipo admite, ou escolha outro tipo de etapa que\\nadmita pontuar ou eliminar conforme a etapa precisa. Se o tipo deveria admitir o\\ncar\xe1ter, o ajuste \xe9 no cadastro de tipos de etapa, feito por quem o gere."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);